import{_ as a,o as i,c as p,y as t}from"./chunks/framework.CNTkXYA8.js";const g=JSON.parse('{"title":"【Ubuntu】基本操作  (条目=11)","description":"","frontmatter":{"title":"【Ubuntu】基本操作  (条目=11)","date":"2018-11-07T16:24:00.000Z"},"headers":[],"relativePath":"blog/ubuntu-11.md","filePath":"source/old_posts/ubuntu-11.md"}'),e={name:"blog/ubuntu-11.md"};function n(l,s,h,d,o,c){return i(),p("div",null,[...s[0]||(s[0]=[t('<p>定义 NAME 为要操作的对象名</p><p>定义 DIR 为文件所在的绝对路径</p><p>所有操作默认在普通用户下进行</p><p>所有软件包默认是指Debian包（deb包）</p><p>1.查看进程</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top</span></span></code></pre></div><p>2.强制结束进程</p><p>PID由top获得：找到进程名字，看左边的PID</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -9 PID</span></span></code></pre></div><p></p><p>3.创建文件夹</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir NAME</span></span></code></pre></div><p></p><p>4.编辑某个文本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gedit DIR/NAME</span></span></code></pre></div><p>用root权限编辑某个文本</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gedit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DIR/NAME</span></span></code></pre></div><p></p><p>5.在已经安装的软件包中查询软件包</p><p>注意这里是大小写敏感的，如果不输出表示没有找到</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dpkg --list | grep NAME</span></span></code></pre></div><p>6.安装软件包</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DIR/NAME</span></span></code></pre></div><p></p><p>7.卸载软件包</p><p>-P表示强制卸载</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAME</span></span></code></pre></div><p></p><p>8.添加源</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-apt-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ppa:NAME</span></span></code></pre></div><p>例：</p><p>添加notepadqq的源</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-apt-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ppa:notepadqq-team/notepadqq</span></span></code></pre></div><p></p><p>9.更新软件包</p><p>一般情况下，添加源后或者安装软件前请务必更新软件包</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p></p><p>10.安装软件</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAME</span></span></code></pre></div><p>例子：</p><p>安装notepadqq</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notepadqq</span></span></code></pre></div><p></p><p>11.转换Windows下编码为UTF-8</p><p>条目下定义DIR2为转换后输出文件绝对路径,定义encoding为转换前的编码</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iconv -c -f encoding -t UTF-8 DIR -o DIR2</span></span></code></pre></div><p>以将目录 ~/ 下的Windows下常用编码GB18030的C++源文件(DIR=~/test.cpp) 转换为UTF-8编码,输出到 ~/ (DIR2=~/test2.cpp) 为例 ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iconv -c -f GB18030 -t UTF-8 ~/test.cpp -o ~/test2.cpp</span></span></code></pre></div><p>Windows下常用编码有:</p><p>GB2312</p><p>GBK 等</p>',52)])])}const u=a(e,[["render",n]]);export{g as __pageData,u as default};
